pub const bun = @import("bun");
pub const css = @import("./css_parser.zig");
const Allocator = std.mem.Allocator;
const Delimiters = css.Delimiters;
const Parser = css.Parser;
const PrintErr = css.PrintErr;
const Printer = css.Printer;
const Result = css.Result;
const generic = css.generic;
const voidWrap = css.voidWrap;
const TextShadow = css.css_properties.text.TextShadow;

pub fn SmallListHeapData(comptime T: type) type {
        return struct {
    len: u32,
    ptr: [*]T,

pub fn initCapacity(allocator: Allocator, capacity: u32) @This() {
            return .{ .len = 0, .ptr = bun.handleOom(allocator.alloc(T, capacity)).ptr };
    }
};
}

pub fn SmallListData(comptime T: type, comptime N: comptime_int) type {
        return union {
    inlined: [N]T,
    heap: SmallListHeapData(T),
};
}

pub inline fn smallListPrefixHelper(comptime T: type, comptime prefix: []const u8, pfs: *css.VendorPrefix, pfi: *const SmallList(T, 1), r: *bun.BabyList(SmallList(T, 1)), alloc: Allocator) void {
        if (bun.bits.contains(css.VendorPrefix, pfs.*, .fromName(prefix))) {
            var images = SmallList(T, 1).initCapacity(alloc, pfi.len());
            _ = &images;
            _ = images.setLen(pfi.len());
            const in_slice = pfi.slice();
            var idx: usize = 0;
            _ = &idx;
            for (cp_mut_slice(&images.slice_mut())) |*out| {
                _ = &out;
                const item = (&in_slice[@as(usize, @intCast(idx))]);
                const image = item.getImage().getPrefixed(alloc, css.VendorPrefix.fromName(prefix));
                (out.*) = item.withImage(alloc, image);
                idx = (idx + 1);
            }
            _ = bun.handleOom(r.append(alloc, images));
        }
}

pub fn SmallList(comptime T: type, comptime N: comptime_int) type {
        return struct {
    capacity: u32 = 0,
    data: Data = .{ .inlined = undefined },

pub fn initInlined(values: []const T) This {
            _ = bun.assert((values.len <= N));
            var res_list = This{ .capacity = values.len, .data = .{ .inlined = undefined } };
            _ = &res_list;
            _ = @memcpy(res_list.data.inlined[0..values.len], values);
            return res_list;
    }

pub fn parse(input: *Parser) Result(@This()) {
            const parseFn = (comptime voidWrap(T, generic.parseFor(T)));
            var values: @This() = .{};
            _ = &values;
            while (true) {
                _ = input.skipWhitespace();
                const empty_ctx: void = undefined;
                switch (input.parseUntilBefore(Delimiters{ .comma = true }, T, empty_ctx, parseFn)) {
.result => |v| {
_ = values.append(input.allocator(), v);
},
.err => |e| {
return .{ .err = e };
},
}
                switch (input.next()) {
.err => {
return .{ .result = values };
},
.result => |t| {
if ((t.* == .comma)) {
                    continue;
                }
                _ = std.debug.panic("Expected a comma", .{});
},
}
            }
            _ = unreachable;
    }

pub fn toCss(self: @This(), dest: *Printer) PrintErr!void {
            const length = self.len();
            var idx: usize = 0;
            _ = &idx;
            for (cp_mut_slice(&self.slice())) |*val| {
                _ = &val;
                _ = try (val.*).toCss(dest);
                if ((idx < (length - 1))) {
                    _ = try dest.delim(44, false);
                }
                idx = (idx + 1);
            }
    }

pub fn fromList(allocator: Allocator, list: std.ArrayListUnmanaged(T)) @This() {
            if ((list.cap > N)) {
                return .{ .capacity = list.cap, .data = .{ .heap = .{ .len = list.len, .ptr = list.ptr } } };
            }
            defer {
            _ = list.deinit(allocator);
            }
            var res_list: @This() = .{ .capacity = list.len, .data = .{ .inlined = undefined } };
            _ = &res_list;
            _ = @memcpy(res_list.data.inlined[0..list.len], list.items[0..list.len]);
            return res_list;
    }

pub fn fromListNoDeinit(list: std.ArrayListUnmanaged(T)) @This() {
